pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] calldata _tos, uint256[] calldata v) public {
        vm.assume(_tos.length == v.length && _tos.length > 0 && _tos.length <= 10);
        // Sum of amounts to be transferred
        uint256 totalAmount = 0;
        for (uint i = 0; i < v.length; i++) {
            vm.assume(v[i] <= type(uint256).max / 1e18); // avoid overflow in mul
            uint256 value = v[i] * 1e18;
            totalAmount += value;
        }
        vm.assume(totalAmount <= address(c.caddress()).balance); // ensure enough balance

        // Simulate the transferFrom by giving caddress enough allowance and balance
        uint256 balanceBefore = address(c.caddress()).balance;

        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        c.transfer(_tos, v);

        uint256 balanceAfter = address(c.caddress()).balance;
        // The reference C makes calls to caddress, which can decrease its balance.
        // The mutant calls from instead, so caddress balance stays unchanged (no calls to it).
        // So the property is: balance of caddress does NOT decrease (it stays the same or increases)
        assertTrue(balanceAfter >= balanceBefore);
    }
}

