import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1000000000000000000);
        }
        // We cannot directly observe the internal call, so we use a property that must hold:
        // The function must not use address(0) as recipient unless _tos contains address(0).
        // Since the bug replaces _tos[i] with address(0), if _tos has no zero address, the bug will be detected.
        bool allNonZero = true;
        for (uint i = 0; i < _tos.length; i++) {
            if (_tos[i] == address(0)) {
                allNonZero = false;
                break;
            }
        }
        if (allNonZero) {
            // If all destination addresses are non-zero, the function should not revert and should complete normally.
            // A revert here would indicate the bug (since address(0) might cause revert in transferFrom call).
            (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));
            assertTrue(success, "transfer should succeed when all destinations are non-zero");
        } else {
            // If address(0) is in the list, we allow any behavior.
        }
    }
}

