pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory _tos, uint256[] memory _v) public {
        // Bound parameters to avoid reverts from internal mul_uint256 overflow
        _tos = boundAddressArray(_tos);
        _v = boundUintArray(_v);

        // Ensure from address is set correctly
        address originalFrom = c.from();

        // Prank as the authorized sender
        address authorizedSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(authorizedSender);

        // Call transfer - this will trigger the call with the bug
        bool success = c.transfer(_tos, _v);

        // After transfer, the from address should remain the same in the correct contract
        // In the buggy version, it would change because of the self-call
        address newFrom = c.from();

        // The from address should be unchanged by transfer operations
        assertTrue(newFrom == originalFrom, "from address should remain unchanged after transfer");
    }

    function boundAddressArray(address[] memory arr) internal pure returns (address[] memory) {
        if (arr.length > 5) {
            uint256 newLen = 5;
            assembly {
                mstore(arr, newLen)
            }
        }
        return arr;
    }

    function boundUintArray(uint256[] memory arr) internal pure returns (uint256[] memory) {
        if (arr.length > 5) {
            uint256 newLen = 5;
            assembly {
                mstore(arr, newLen)
            }
        }
        // Bound each value to avoid overflow in mul_uint256
        for (uint i = 0; i < arr.length; i++) {
            if (arr[i] > 100000) {
                arr[i] = 100000;
            }
        }
        return arr;
    }
}

